<div class="toolbar"><p class="muted">选择套餐后在下方统一编辑，列表中不再挤放输入框。</p><div class="toolbar-right"><a class="btn" href="/admin/shop-packages#package-editor">新增套餐</a></div></div>
<section class="card table-card"><div class="table-scroll"><table><thead><tr><th>套餐名称</th><th>平台 / 功能</th><th>价格</th><th>有效期</th><th>设备数</th><th>状态</th><th>操作</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><strong><?= e($r['name']) ?></strong><div class="muted">ID <?= (int)$r['id'] ?></div></td><td><?= e(implode('、',array_map(function($id){return lc_names()[$id] ?? $id;},$r['platforms_arr']))) ?><div class="muted"><?= e(implode('、',array_map(function($id){return lc_feature_names()[$id] ?? $id;},$r['features_arr']))) ?></div></td><td>¥<?= number_format($r['price'],2) ?></td><td><?= (int)$r['days'] ?> 天</td><td><?= (int)($r['device_limit'] ?: 1) ?> 台</td><td><span class="badge <?= $r['active']?'ok':'muted' ?>"><?= $r['active']?'启用':'停用' ?></span></td><td class="ops"><a class="btn ghost" href="?edit=<?= (int)$r['id'] ?>#package-editor">编辑</a><form method="post" action="/admin/shop-packages" onsubmit="return confirm('删除该套餐？')"><?= csrf_field() ?><input type="hidden" name="delete_id" value="<?= (int)$r['id'] ?>"><button class="btn ghost danger">删除</button></form></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="7" class="empty">暂无套餐，请在下方新增。</td></tr><?php endif; ?></tbody></table></div></section>
<?php $editing=null;foreach($rows as $entry){if((int)($_GET['edit'] ?? 0)===(int)$entry['id'])$editing=$entry;}$edit=$editing ?: ['id'=>0,'name'=>'','price'=>'','days'=>365,'device_limit'=>2,'active'=>1,'platforms_arr'=>['alibaba'],'features_arr'=>['listing','category']]; ?>
<section class="card" id="package-editor"><div class="section-title"><div><h2><?= $editing?'编辑套餐：'.e($edit['name']):'新增套餐' ?></h2><p class="muted">价格、有效期和设备数独立填写。已购买订单的套餐快照保持不变。</p></div><?php if($editing): ?><a href="/admin/shop-packages#package-editor">取消编辑</a><?php endif; ?></div>
<form method="post" action="/admin/shop-packages"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$edit['id'] ?>"><div class="form-grid">
<label>套餐名称<input name="name" value="<?= e($edit['name']) ?>" required placeholder="例如：国际站年度套餐…"></label>
<label>价格（元）<input name="price" type="number" step="0.01" min="0" value="<?= e((string)$edit['price']) ?>" required></label>
<label>有效天数<input name="days" type="number" min="1" value="<?= (int)$edit['days'] ?>" required></label>
<label>允许设备数<input name="device_limit" type="number" min="1" value="<?= (int)$edit['device_limit'] ?>" required></label>
<label>包含平台（平台 ID，逗号分隔）<input name="platforms" value="<?= e(implode(',',$edit['platforms_arr'])) ?>" required><span class="hint">可用：<?= e(implode('、',array_keys(lc_registry()))) ?></span></label>
<label>包含功能（功能 ID，逗号分隔）<input name="features" value="<?= e(implode(',',$edit['features_arr'])) ?>" required><span class="hint">功能定义见<a href="/admin/platforms">平台与接口</a>。</span></label>
<label>套餐状态<select name="active"><option value="1" <?= $edit['active']?'selected':'' ?>>启用</option><option value="0" <?= !$edit['active']?'selected':'' ?>>停用</option></select></label>
</div><div class="form-actions"><button class="btn" type="submit"><?= $editing?'保存套餐':'新增套餐' ?></button></div></form></section>
